/// <summary>
///  AVA_011632_DataEntitySalesImport
/// </summary>
/// <param name = "_entityCtx">DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">DataEntityDataSourceRuntimeContext</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    SalesTable lsalesTable;
    next mapEntityToDataSource(_entityCtx, _dataSourceCtx);
    switch (_dataSourceCtx.name())
    {
        case dataEntityDataSourceStr(SalesOrderHeaderV3Entity, SalesTable) :
            lsalesTable = _dataSourceCtx.getBuffer();
            if (this.isFieldSet(fieldNum(SalesOrderHeaderV3Entity, salesType)))
            {
                lsalesTable.SalesType = this.SalesType;
            }
            else
            {
                lsalesTable.SalesType = SalesType::Sales;
            }
        default:
            break;
    }
}
